'use client'

import { useState } from 'react'
import { CalendarIcon } from 'lucide-react'
import { format } from 'date-fns'

import { cn, parseAllowedPrimitive } from '@/lib/utils'

import { type AutocompleteWrapperProps, AutocompleteWrapper as AutocompletePrimitive } from './autocomplete'
import { type selectProps, SelectWrapper as SelectPrimitiveWrapper } from './select'
import { type ComboboxWrapperProps, ComboboxWrapper as Combobox } from './combobox'
import { type CheckboxWrapperProps, CheckboxWrapper as Checkbox } from './checkbox'
import { Field, FieldLabel, FieldSet, FieldLegend, FieldError } from './field'
import { type RadioWrapperProps, RadioWrapper as Radio } from './radio'
import { Popover, PopoverContent, PopoverTrigger } from './popover'
import { NumberFieldWrapper } from './number-field'
import { Calendar } from './calendar'
import { Textarea } from './textarea'
import { Slider } from './slider'
import { Button } from './button'
import { Switch } from './switch'
import { Input } from './input'

type BaseProps = {
  name: string
  label?: React.ReactNode
  error?: { message?: string }
  invalid?: boolean
  className?: string
}

function labelString(label: React.ReactNode): string | undefined {
  return typeof label === 'string' ? label : undefined
}

type InputProps = BaseProps & React.InputHTMLAttributes<HTMLInputElement>
export function InputWrapper({
  name,
  label,
  error,
  invalid,
  className,
  type = 'text',
  placeholder,
  ...props
}: InputProps) {
  const isInvalid = invalid || !!error

  return (
    <Field className={className} invalid={isInvalid}>
      {label && <FieldLabel htmlFor={name}>{label}</FieldLabel>}
      <Input
        id={name}
        name={name}
        type={type}
        placeholder={placeholder || (labelString(label) && `Enter ${labelString(label)}`)}
        aria-invalid={isInvalid}
        {...props}
      />
      <FieldError errors={[error]} />
    </Field>
  )
}

type TextareaProps = BaseProps & React.TextareaHTMLAttributes<HTMLTextAreaElement>
export function TextareaWrapper({
  name,
  label,
  error,
  invalid,
  className,
  placeholder,
  ...rest
}: TextareaProps) {
  const isInvalid = invalid || !!error

  return (
    <Field className={className} invalid={isInvalid}>
      {label && <FieldLabel htmlFor={name}>{label}</FieldLabel>}
      <Textarea
        id={name}
        name={name}
        placeholder={placeholder || (labelString(label) && `Enter ${labelString(label)}`)}
        aria-invalid={isInvalid}
        {...rest}
      />
      <FieldError errors={[error]} />
    </Field>
  )
}

type RadioProps = BaseProps &
  Omit<RadioWrapperProps, 'value' | 'onValueChange' | 'as'> & {
    value?: allowedPrimitiveT
    onValueChange?: (value: allowedPrimitiveT) => void
  }
export function RadioWrapper({
  name,
  label,
  error,
  invalid,
  className,
  value,
  onValueChange,
  ...props
}: RadioProps) {
  const isInvalid = invalid || !!error

  return (
    <FieldSet className={cn(className)}>
      {label && <FieldLegend variant="label">{label}</FieldLegend>}
      <Radio
        {...props}
        as={FieldLabel}
        value={value ? String(value) : undefined}
        onValueChange={val => onValueChange?.(parseAllowedPrimitive(val))}
        aria-invalid={isInvalid}
      />
      <FieldError errors={[error]} />
    </FieldSet>
  )
}

type CheckboxProps = BaseProps &
  Omit<CheckboxWrapperProps, 'value' | 'onValueChange' | 'as'> & {
    value?: allowedPrimitiveT[]
    onValueChange?: (value: allowedPrimitiveT[]) => void
  }
export function CheckboxWrapper({
  name,
  label,
  error,
  invalid,
  className,
  value = [],
  onValueChange,
  ...props
}: CheckboxProps) {
  const isInvalid = invalid || !!error

  return (
    <FieldSet className={cn(className)}>
      {label && <FieldLegend variant="label">{label}</FieldLegend>}
      <Checkbox
        orientation="horizontal"
        {...props}
        as={FieldLabel}
        value={value.map(String)}
        onValueChange={vals => onValueChange?.(vals.map(parseAllowedPrimitive))}
        aria-invalid={isInvalid}
      />
      <FieldError errors={[error]} />
    </FieldSet>
  )
}

type SwitchProps = BaseProps & {
  checked?: boolean
  onCheckedChange?: (checked: boolean) => void
}
export function SwitchWrapper({
  name,
  label,
  error,
  invalid,
  className,
  checked,
  onCheckedChange,
}: SwitchProps) {
  const isInvalid = invalid || !!error

  return (
    <Field className={className} invalid={isInvalid}>
      <div className="flex items-center justify-between gap-4">
        {label && (
          <FieldLabel htmlFor={name} className="font-normal">
            {label}
          </FieldLabel>
        )}
        <Switch
          id={name}
          checked={checked}
          onCheckedChange={onCheckedChange}
          aria-label={typeof label === 'string' ? label : name}
          aria-invalid={isInvalid}
        />
      </div>
      <FieldError errors={[error]} />
    </Field>
  )
}

type SelectProps = BaseProps &
  Omit<selectProps, 'value' | 'onValueChange'> & {
    value?: allowedPrimitiveT
    onValueChange?: (value: allowedPrimitiveT) => void
  }
export function SelectWrapper({
  name,
  label,
  error,
  invalid,
  className,
  options,
  placeholder,
  value,
  onValueChange,
  ...props
}: SelectProps) {
  const isInvalid = invalid || !!error

  return (
    <Field className={className} invalid={isInvalid}>
      {label && <FieldLabel htmlFor={name}>{label}</FieldLabel>}
      <SelectPrimitiveWrapper
        {...props}
        id={name}
        options={options}
        value={value ? String(value) : undefined}
        placeholder={placeholder ?? (labelString(label) && `Select ${labelString(label)}`)}
        onValueChange={val => onValueChange?.(parseAllowedPrimitive(val as any))}
        aria-invalid={isInvalid}
      />
      <FieldError errors={[error]} />
    </Field>
  )
}

type DatePickerProps = BaseProps &
  Omit<React.ComponentProps<typeof Calendar>, 'selected' | 'onSelect'> & {
    value?: Date
    onSelect?: (date: Date | undefined) => void
  }
export function DatePickerWrapper({
  name,
  label,
  error,
  invalid,
  className,
  value,
  onSelect,
  ...calendarProps
}: DatePickerProps) {
  const [open, setOpen] = useState(false)
  const isInvalid = invalid || !!error

  return (
    <Field className={className} invalid={isInvalid}>
      {label && <FieldLabel htmlFor={name}>{label}</FieldLabel>}
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger
          render={
            <Button
              id={name}
              variant={'outline'}
              className={cn('w-full pl-3 text-left font-normal', !value && 'text-muted-foreground')}
              aria-invalid={isInvalid}
            >
              {value ? format(value, 'dd/MM/yyyy') : <span>Pick a date</span>}
              <CalendarIcon className="ml-auto h-4 w-4 opacity-50" />
            </Button>
          }
        />

        <PopoverContent className="w-auto p-0" align="start">
          <Calendar
            autoFocus
            mode="single"
            captionLayout="dropdown"
            selected={value}
            onSelect={date => {
              onSelect?.(date)
              setOpen(false)
            }}
            defaultMonth={value}
            {...(calendarProps as any)}
          />
        </PopoverContent>
      </Popover>
      <FieldError errors={[error]} />
    </Field>
  )
}

type ComboboxProps = BaseProps & ComboboxWrapperProps
export function ComboboxWrapper({
  name,
  label,
  error,
  invalid,
  className,
  placeholder,
  value,
  onValueChange,
